const e=[{id:"northwind-organic-search",slug:"northwind-organic-search",category:"SEO and content",title:"How Northwind made organic search its biggest revenue channel",summary:"A step by step look at the technical fixes, the 40 article plan and the PR that took organic past paid social in six months.",authorSlug:"mei-tanaka",date:"19 Oct 2026",readTime:"14 min read",featured:!0,coverImage:"/assets/images/products/product-coffee.webp",inlineImage:"/assets/images/about/about-meeting-main.webp",inlineCaption:"Walking the Northwind team through the price index results.",toc:["Fix the foundations first","Build a topic map around buying intent","Earn links with real data","What to take from it"],lead:["Six months ago organic drove 11% of Northwind's revenue. Today it is their biggest and cheapest channel.","Paid social carried the business and every new customer cost more than the last. Here is exactly what we changed, in the order we changed it."],section1Title:"Fix the foundations first",section1Body:"We started with a technical audit. Slow product pages, duplicate collection URLs and a broken sitemap were quietly capping every ranking. Two sprints of fixes lifted crawl coverage before we wrote a single article.",stats:[{value:"+38%",label:"crawl coverage"},{value:"40",label:"new guides"},{value:"26",label:"publications linking"}],section2Title:"Build a topic map around buying intent",section2Body:"Instead of chasing volume, we mapped the questions people ask right before they buy: brewing guides, bean comparisons and subscription questions. Every article is tied to a product page.",calloutQuote:"“We wrote for the person holding a bag of beans, not for the algorithm.”",section3Title:"Earn links with real data",section3Items:["Annual coffee price index built from Northwind's own sales data.","Targeted outreach to coffee writers, roasters and food editors.","Links from 26 publications pushing category pages onto page one.","Internal linking from every guide straight to matching subscriptions."],section4Title:"What to take from it",section4Body:"Organic compounds when the site is technically clean, the content answers buying questions and the links come from genuinely useful data. None of it is a trick, and all of it is repeatable."},{id:"fewer-google-ads-campaigns",slug:"fewer-google-ads-campaigns",category:"Paid search",title:"Why your Google Ads account needs fewer campaigns, not more",summary:"Splitting budgets across 40 campaigns starves smart bidding of conversion data. Here is how we consolidate accounts without losing control.",authorSlug:"clara-benet",date:"12 Oct 2026",readTime:"9 min read",featured:!1,coverImage:"/assets/images/about/about-meeting-main.webp",inlineImage:"/assets/images/about/about-collaboration.webp",inlineCaption:"Our team mapping search intent for a B2B client.",toc:["The problem with more","What consolidation looks like","Our four step rebuild","What happened next"],lead:["Most accounts we audit have between 40 and 120 campaigns. Most of them would make more money with eight.","Every new campaign splits your budget and your data. Google's bidding needs volume to learn, and a small campaign never gets enough of it. The result is higher costs and reports nobody can read."],section1Title:"The problem with more",section1Body:"When we audited Oakline last year they had 64 search campaigns. Thirty of them spent less than £20 a day. None of those thirty had enough conversions for smart bidding to work.",stats:[{value:"64",label:"campaigns before"},{value:"9",label:"campaigns after"},{value:"−38%",label:"cost per demo"}],section2Title:"What consolidation looks like",section2Body:"We group by intent and margin, not by product line. One campaign for people ready to buy, one for people comparing, one for brand. Everything else is a test with an end date.",calloutQuote:"“We stopped asking which campaign to add and started asking which one to switch off.”",section3Title:"Our four step rebuild",section3Items:["Export every search term from the last 12 months.","Group terms by intent and by gross margin.","Rebuild into no more than ten campaigns.","Review weekly and kill anything without a clear job."],section4Title:"What happened next",section4Body:"Within eight weeks Oakline's cost per demo fell 38% and their weekly report shrank from four pages to one. The account is easier to run, and the bidding finally has enough data to work."},{id:"creative-testing-system",slug:"creative-testing-system",category:"Paid social",title:"The creative testing system behind 30 Meta ads a month",summary:"How we brief in batches, judge ads within 72 hours on early signals, and recycle winning angles into fresh hooks every Friday.",authorSlug:"tom-hale",date:"05 Oct 2026",readTime:"7 min read",featured:!1,coverImage:"/assets/images/about/about-collaboration.webp",inlineImage:"/assets/images/careers/careers-workshop.webp",inlineCaption:"Reviewing weekly creative test scores in the studio.",toc:["Brief in batches","Judge on early signals","Keep the process boring","Recycle what works"],lead:["Creative is the biggest lever left on Meta. The brands that win test the most ideas, not the biggest budgets.","We ship around thirty new ads a month for each paid social client. This is the system that keeps that volume useful instead of chaotic."],section1Title:"Brief in batches",section1Body:"Every month starts with ten angles, each with three executions. That gives us thirty ads that test ideas, not just colours or button text.",stats:[{value:"30",label:"new ads a month"},{value:"72h",label:"to first read"},{value:"3x",label:"more ideas tested"}],section2Title:"Judge on early signals",section2Body:"We look at thumb stop rate and cost per click in the first 72 hours, then let only the top performers spend. Losers are paused before they eat the budget.",calloutQuote:"“An ad that nobody stops for cannot sell anything, however good the offer.”",section3Title:"Keep the process boring",section3Items:["Collect angles from reviews, comments and sales calls.","Write three hooks for every angle.","Launch on Monday, read on Thursday.","Move budget to winners every Friday."],section4Title:"Recycle what works",section4Body:"Winning angles go back into the next brief with new hooks, so learning compounds instead of resetting every month."},{id:"topic-map-buying-intent",slug:"topic-map-buying-intent",category:"SEO and content",title:"How to build a topic map that ranks for buying intent",summary:"Most content plans chase keyword volume and never convert. Start from your products and map the questions buyers ask right before checkout.",authorSlug:"mei-tanaka",date:"28 Sep 2026",readTime:"11 min read",featured:!1,coverImage:"/assets/images/careers/careers-workshop.webp",inlineImage:"/assets/images/about/about-meeting-main.webp",inlineCaption:"Prioritising 40 buying-intent guides for a SaaS client.",toc:["Start from the product","Score by intent and effort","Write for the buyer","Link it together"],lead:["A topic map is a plan for which questions you will answer and in what order. Done well, it turns content into a sales channel.","Most content plans start with keyword volume. Ours start with the product, because that is where the revenue is."],section1Title:"Start from the product",section1Body:"List every product and the questions people ask before buying it. Those questions are your first articles, and they usually have far less competition than broad terms.",stats:[{value:"120",label:"questions mapped"},{value:"40",label:"priority topics"},{value:"6",label:"months to rank"}],section2Title:"Score by intent and effort",section2Body:"We rank each topic by how close it sits to a purchase and how hard it will be to rank. High intent, low effort topics go first.",calloutQuote:"“Traffic that never buys is just a bigger server bill.”",section3Title:"Write for the buyer",section3Items:["Answer the question in the first paragraph.","Show the product where it genuinely helps.","Add one clear next step at the end.","Refresh the page every six months."],section4Title:"Link it together",section4Body:"Every article links to the product it supports and to two related guides, so authority flows to the pages where revenue happens."},{id:"five-email-flows",slug:"five-email-flows",category:"Lifecycle",title:"Five email flows every ecommerce brand should run",summary:"Automated lifecycle flows generate a third of email revenue for our clients without extra ad spend. Here are the five we build first.",authorSlug:"priya-shah",date:"21 Sep 2026",readTime:"6 min read",featured:!1,coverImage:"/assets/images/about/about-collaboration.webp",inlineImage:"/assets/images/products/product-skincare.webp",inlineCaption:"Mapping post-purchase timing around real product usage.",toc:["Welcome and browse abandonment","Cart and checkout abandonment","Post purchase","Win back"],lead:["Campaigns get the attention, but flows do the heavy lifting. For most of our ecommerce clients they drive a third of email revenue.","These five run in every ecommerce account we manage. None of them need a big list, just clean data and a clear job."],section1Title:"Welcome and browse abandonment",section1Body:"Introduce the brand, then follow up on what people looked at. Together they turn first time visitors into first time buyers.",stats:[{value:"5",label:"core flows"},{value:"48h",label:"cart window"},{value:"1 in 3",label:"email revenue"}],section2Title:"Cart and checkout abandonment",section2Body:"Two to three emails within 48 hours, with the product front and centre. We hold back discounts until the last email so we do not train people to wait.",calloutQuote:"“The best flow is the one a customer barely notices, because it simply helps.”",section3Title:"Post purchase",section3Items:["Thank the customer and confirm what happens next.","Help them get the most from the product.","Ask for a review once it has arrived.","Suggest one product that fits what they bought."],section4Title:"Win back",section4Body:"Lapsed buyers get a reason to return: something new, something useful or a reminder of what they liked. A discount is the last resort, not the first."},{id:"one-page-cfo-report",slug:"one-page-cfo-report",category:"Reporting",title:"The one page report your CFO will actually read",summary:"Nobody in finance wants a 30-slide deck of impressions. Here is the single-page Monday revenue report we send every client.",authorSlug:"clara-benet",date:"14 Sep 2026",readTime:"5 min read",featured:!1,coverImage:"/assets/images/about/about-meeting-main.webp",inlineImage:"/assets/images/about/about-collaboration.webp",inlineCaption:"Reviewing the Monday one-page revenue readout.",toc:["Lead with revenue","One row per channel","Keep the format fixed","End with decisions"],lead:["Finance does not want impressions. They want to know what was spent, what came back and what happens next.","We replaced a 30 page monthly deck with a single page. Our clients' finance teams now read it, and they ask better questions."],section1Title:"Lead with revenue",section1Body:"The top line shows spend, revenue and blended return for the month, compared with target. If that line is all someone reads, they still know how marketing did.",stats:[{value:"30",label:"pages before"},{value:"1",label:"page after"},{value:"5 min",label:"to read"}],section2Title:"One row per channel",section2Body:"Each channel gets a single line: spend, revenue, cost per acquisition and a short note in plain English. No charts that need a legend.",calloutQuote:"“If finance cannot read it in five minutes, it is not a report, it is homework.”",section3Title:"Keep the format fixed",section3Items:["Same order every month.","Same definitions for every number.","Targets shown next to actuals.","Notes written in full sentences."],section4Title:"End with decisions",section4Body:"The last section lists what we will change next month and why, so the report drives action instead of filling a folder."},{id:"tiktok-for-b2b",slug:"tiktok-for-b2b",category:"Paid social",title:"TikTok for B2B: what worked in our last 12 tests",summary:"We ran 12 controlled B2B TikTok tests measured strictly on booked demos. Unpolished founder explainers beat studio ads every time.",authorSlug:"tom-hale",date:"07 Sep 2026",readTime:"8 min read",featured:!1,coverImage:"/assets/images/careers/careers-workshop.webp",inlineImage:"/assets/images/products/product-fashion.webp",inlineCaption:"Testing short-form vertical hooks across B2B cohorts.",toc:["Founder explainers","Customer reactions","How we ran the tests","What did not work"],lead:["B2B on TikTok sounds like a stretch. Across twelve tests for SaaS and services clients, three formats consistently produced pipeline.","We ran every test with the same budget, the same audience rules and the same goal: booked demos, not views."],section1Title:"Founder explainers",section1Body:"Short, unpolished videos where a founder explains one problem outperformed every produced ad. People trusted the person more than the brand.",stats:[{value:"12",label:"tests run"},{value:"3",label:"formats that worked"},{value:"−42%",label:"cost per demo"}],section2Title:"Customer reactions",section2Body:"Real customers describing the before and after drove the cheapest demo bookings. We kept them under thirty seconds and added captions for silent viewing.",calloutQuote:"“Nobody on TikTok wants an ad. They will happily watch someone solve a problem.”",section3Title:"How we ran the tests",section3Items:["One format per test, nothing else changed.","Two weeks per test at a fixed daily budget.","Success measured on demos, not clicks.","Winners rerun with new hooks to confirm."],section4Title:"What did not work",section4Body:"Polished brand videos and generic product demos struggled to hold attention past three seconds. Anything that looked like an ad was treated like one."}];export{e as a};
